const expected = $env.SAIBAI_SHOPIFY_WEBHOOK_TOKEN || $env.SAIBAI_ECOM_WEBHOOK_TOKEN || '';
const headers = $json.headers || {};
const received = String(headers['x-veltrus-token'] || headers['X-Veltrus-Token'] || '');
if (expected && received !== expected) {
  throw new Error('Unauthorized Shopify order webhook.');
}
const raw = $json.body ?? $json;
const order = typeof raw === 'string' ? JSON.parse(raw) : raw;
const orderId = String(order.id || order.order_id || '').trim();
if (!orderId) throw new Error('Shopify order id required');
const orderNumber = String(order.order_number || order.name || orderId);
const revenue = Number(order.total_price || order.current_total_price || 0);
const currency = String(order.currency || 'BRL');
const email = String(order.email || order.contact_email || '').trim();
const noteAttrs = order.note_attributes || [];
let utmSource = '';
for (const a of noteAttrs) {
  if (String(a.name || '').toLowerCase() === 'utm_source') utmSource = String(a.value || '');
}
const landing = String(order.landing_site || order.referring_site || '—');
const lines = [
  'Emporio Saibai · PEDIDO PAGO',
  `#${orderNumber}`,
  `Shopify ID: ${orderId}`,
  `Valor: R$ ${revenue.toFixed(2).replace('.', ',')} ${currency}`,
  email ? `Email: ${email}` : null,
  utmSource ? `UTM: ${utmSource}` : `Origem: ${landing}`,
  `Hora: ${new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' })}`,
  '',
  'Webhook: orders/paid · byinbz-0k.myshopify.com',
].filter(Boolean);
const phones = String($env.SAIBAI_SALES_WHATSAPP || $env.SAIBAI_ALERT_WHATSAPP_LIST || '')
  .split(',')
  .map((p) => p.trim().replace(/\D/g, ''))
  .filter(Boolean);
if (!phones.length) throw new Error('SAIBAI_SALES_WHATSAPP ausente');
return phones.map((phone) => ({ json: { phone, text: lines.join('\n'), orderId, orderNumber, revenue } }));
